/* ==== atlas-navigation.css ==== */
/* Choosing a reaction and reading it are separate screens. */
.atlas-browser { min-width: 0; }
.atlas-catalog { max-width: 1100px; margin-inline: auto; scroll-margin-top: 110px; }
.atlas-catalog-controls { display: grid; grid-template-columns: minmax(220px, 1fr) minmax(160px, 230px) auto; gap: 22px; align-items: end; padding: 8px 0 26px; border-bottom: 1px solid var(--line); }
.atlas-catalog-controls .atlas-search-label,
.atlas-catalog-controls .atlas-family-label { display: grid; min-width: 0; gap: 9px; font-size: 13px; color: var(--muted); }
.atlas-catalog-controls input[type="search"],
.atlas-catalog-controls select { width: 100%; max-width: none; min-width: 0; height: 45px; margin: 0; padding: 9px 12px; color: var(--ink); font: inherit; font-size: 16px; background: #fffdf8; border: 1px solid #c8cbc1; border-radius: 6px; }
.atlas-catalog-controls .atlas-interactive-filter { margin: 0; padding: 12px 0; font-size: 13px; white-space: nowrap; }
.atlas-results-heading { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 8px 20px; margin: 22px 0 8px; color: var(--muted); font-size: 13px; }
.atlas-results-heading p { margin: 0; color: var(--ink); }
.atlas-results-heading > span { font-size: 12px; }
.atlas-catalog-list { display: grid; gap: 0; }
.atlas-catalog-list .atlas-link { display: grid; grid-template-columns: minmax(0, 1fr) minmax(110px, 160px) 95px 20px; gap: 18px; align-items: center; width: 100%; min-height: 78px; margin: 0; padding: 17px 10px; border: 0; border-bottom: 1px solid var(--line); border-radius: 0; background: transparent; text-align: left; color: var(--ink); }
.atlas-catalog-list .atlas-link strong { display: block; margin: 0; font-size: 16px; line-height: 1.65; font-weight: 550; overflow-wrap: anywhere; }
.atlas-catalog-list .atlas-link span,
.atlas-catalog-list .atlas-link small { display: block; margin: 0; color: var(--muted); font-size: 12px; line-height: 1.6; }
.atlas-catalog-list .atlas-link .atlas-route-arrow { text-align: right; color: var(--copper); font-size: 20px; }
.atlas-catalog-list .atlas-link:hover { background: #eeeae0; }
.atlas-catalog-list .atlas-link[aria-current="true"] { border-left: 3px solid var(--copper); padding-left: 7px; background: #f8eee3; }
.atlas-catalog-list .atlas-link[aria-current="true"] strong { color: #984b32; }
.atlas-catalog-list .atlas-link:focus-visible { position: relative; outline: 2px solid var(--copper); outline-offset: 2px; z-index: 1; }
.atlas-show-more { display: block; min-height: 44px; padding: 10px 20px; margin: 24px auto 0; color: var(--ink); background: #fffdf8; border: 1px solid #c8cbc1; border-radius: 6px; font-size: 14px; }
.atlas-show-more[hidden] { display: none; }
.atlas-empty { padding: 34px 0; color: var(--muted); font-size: 15px; line-height: 1.8; }
.atlas-catalog-supplement { margin-top: 45px; padding-top: 20px; border-top: 1px solid var(--line); }
.atlas-catalog-supplement > details { margin: 0 0 18px; padding: 0; border: 0; background: transparent; }
.atlas-catalog-supplement > details > summary { font-size: 13px; }
.atlas-catalog-supplement .atlas-curated { margin: 18px 0 24px; }
.atlas-reader-navigation { display: flex; align-items: center; margin: 0 0 22px; }
.atlas-reader-navigation .text-button { font-size: 14px; padding: 5px 0; color: var(--muted); }
.atlas-reader-navigation .text-button:hover { color: var(--copper); background: transparent; }
.atlas-reader #atlas-detail { min-width: 0; }
@media (max-width: 900px) {
 .atlas-catalog-controls { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 18px; }
 .atlas-catalog-controls .atlas-interactive-filter { grid-column: 1 / -1; padding: 0; }
 .atlas-catalog-list .atlas-link { grid-template-columns: minmax(0, 1fr) 110px 20px; gap: 12px; }
 .atlas-catalog-list .atlas-link .atlas-route-family { display: none; }
}
@media (max-width: 540px) {
 .atlas-catalog-controls { grid-template-columns: minmax(0, 1fr); gap: 17px; padding-bottom: 22px; }
 .atlas-catalog-controls .atlas-interactive-filter { grid-column: auto; font-size: 14px; }
 .atlas-results-heading { margin-top: 20px; }
 .atlas-results-heading > span { display: none; }
 .atlas-catalog-list .atlas-link { grid-template-columns: minmax(0, 1fr) 18px; gap: 5px 12px; padding: 17px 6px; }
 .atlas-catalog-list .atlas-link strong { grid-column: 1; font-size: 16px; }
 .atlas-catalog-list .atlas-link small { grid-column: 1; font-size: 12px; }
 .atlas-catalog-list .atlas-link .atlas-route-arrow { grid-column: 2; grid-row: 1 / 3; }
 .atlas-catalog-list .atlas-link[aria-current="true"] { padding-left: 3px; }
 .atlas-catalog-supplement { margin-top: 32px; }
 .atlas-reader-navigation { margin-bottom: 16px; }
}

/* ==== gi-bond-observer.css ==== */
/* GI only: the existing concept, overview positions and local graph controls. */
.gi-stage-grid{row-gap:.5rem}
.gi-stage-grid>.gi-step-heading{grid-column:1 / -1;min-width:0}
.gi-step-heading .atlas-current-equation{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.25rem .75rem;align-items:start;border:0;padding:0}
.gi-step-heading .atlas-current-equation>span{display:none}
.gi-step-heading .atlas-current-equation h3{grid-column:1 / -1;margin:0;font-size:1rem;line-height:1.4;overflow-wrap:anywhere}
.gi-step-heading .step-formula{grid-column:1;grid-row:2;margin:0;padding:.25rem .5rem;font-size:.84rem;line-height:1.45;overflow-wrap:anywhere}
.gi-step-heading .atlas-step-explanation{grid-column:2;grid-row:2;align-self:center;justify-self:end;min-width:0;margin:0}
.gi-step-heading .atlas-step-explanation[open]{grid-column:1 / -1;grid-row:3;justify-self:stretch}
.gi-step-heading .atlas-step-explanation summary{font-size:.75rem;line-height:1.4}
.gi-step-heading .atlas-step-explanation p{margin:.375rem 0;font-size:.8125rem;line-height:1.6;overflow-wrap:anywhere}
.gi-overview-column .gi-step-sequence{order:-2;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.3125rem;margin:0 0 .375rem}
.gi-step-sequence button{min-width:0;min-height:1.875rem;padding:.25rem .375rem;font-size:.75rem;line-height:1.3;overflow-wrap:anywhere}
.gi-step-sequence button>span{display:inline;margin:0 .25rem 0 0;font:inherit}
#atlas-detail:not(:has(#atlas-mechanism-player)) .gi-overview-column .atlas-progress{gap:.375rem .5rem;margin:0 0 .5rem;padding:.5rem .625rem}
.gi-overview-column .atlas-progress .section-heading{min-width:0;gap:.375rem;flex-wrap:wrap}
.gi-overview-column .atlas-progress #atlas-step-count{font-size:.75rem}
.gi-overview-column .atlas-progress .history-controls{gap:.375rem}
.gi-overview-column .atlas-progress button{min-height:1.875rem;padding:.25rem .5rem;font-size:.75rem;line-height:1.35}
.gi-viewer-card .atlas-viewer{height:clamp(20rem,calc(100vh - 33.6875rem),26rem)}
.gi-viewer-card .atlas-model-heading{gap:.5rem;flex-wrap:wrap;padding:.5rem .875rem .25rem;font-size:.85rem}
.gi-viewer-card #atlas-model-name{min-width:0;flex:1}
.gi-viewer-card .model-status{padding:0 .875rem .375rem;font-size:.75rem;line-height:1.4}
.gi-observation-tools{display:flex;align-items:flex-start;gap:.5rem;flex-wrap:wrap;padding:.375rem .875rem .5rem;border-top:1px solid #ffffff17;background:#ffffff04}
.gi-bond-observer{flex:1 1 18rem;min-width:0;padding:0;color:#dce9e8}
.gi-bond-controls{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;min-width:0}
.gi-bond-caption{font-size:.75rem;color:#b6c9c6;margin-right:.125rem}
.gi-bond-controls button{font:inherit;font-size:.82rem;line-height:1.35;padding:.375rem .625rem;min-height:2rem;min-width:0;max-width:100%;overflow-wrap:anywhere;border:1px solid #718c8c;background:#ffffff06;border-radius:.3125rem;color:inherit}
.gi-bond-controls button[aria-pressed="true"]{background:#234d43;border-color:#70d5b9;box-shadow:inset 0 0 0 1px #70d5b9}
.gi-bond-controls button:focus-visible{outline:2px solid #70d5b9;outline-offset:3px}
.gi-bond-controls button:disabled{opacity:.6;cursor:default}
.gi-bond-readout,.gi-bond-caveat{margin:.25rem 0 0;font-size:.75rem;line-height:1.5;overflow-wrap:anywhere}
.gi-bond-caveat{padding-left:.5rem;border-left:2px solid #d8b66e;color:#ebcf9a}
.gi-bond-caveat[hidden]{display:none}
.gi-endpoint-controls{display:flex;align-items:center;gap:.25rem;flex:0 1 auto;flex-wrap:wrap;min-width:0;max-width:100%}
.gi-endpoint-controls[hidden]{display:none}
.gi-endpoint-controls button{font:inherit;font-size:.8rem;line-height:1.3;padding:.375rem .5625rem;min-height:2rem;min-width:0;max-width:100%;overflow-wrap:anywhere;border:1px solid #718c8c;background:#ffffff06;border-radius:.3125rem;color:#dce9e8}
.gi-endpoint-controls button[aria-pressed="true"]{background:#234d43;border-color:#70d5b9}
.gi-endpoint-controls button:focus-visible{outline:2px solid #70d5b9;outline-offset:3px}

/* ==== food-experiments.css ==== */
/* Lesson-sized interactions; each experiment owns one question and one plot. */
.food-experiment {
  --exp-ink: var(--ink, #203038);
  --exp-muted: var(--muted, #58666a);
  --exp-line: var(--line, #dddcd2);
  --exp-accent: var(--copper, #b9543a);
  color: var(--exp-ink);
  width: 100%;
  min-width: 0;
  max-width: 680px;
  margin: 0 auto;
  line-height: 1.65;
}
.food-experiment *, .food-experiment *::before, .food-experiment *::after { box-sizing: border-box; }
.food-exp-heading { margin-bottom: 20px; }
.food-exp-kicker { margin: 0 0 8px; color: var(--exp-accent); font-size: 13px; letter-spacing: .12em; }
.food-exp-heading h3 { margin: 0; font-size: clamp(19px, 2.1vw, 25px); line-height: 1.5; font-weight: 600; }
.food-exp-hint { margin: 8px 0 0; color: var(--exp-muted); font-size: 13px; }
.food-exp-stage { margin: 0 0 24px; padding: 22px 24px 14px; background: #f6f7f8; border-radius: 12px; }
.food-exp-result { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 14px; min-height: 55px; }
.food-exp-value { color: var(--exp-accent); font-size: clamp(31px, 3.4vw, 42px); font-weight: 500; letter-spacing: -.045em; font-variant-numeric: tabular-nums; line-height: 1.25; }
.food-exp-result-label { color: var(--exp-muted); font-size: 13px; }
.food-exp-figure { max-width: 490px; margin: 0 auto; }
.food-exp-figure svg { display: block; width: 100%; height: auto; overflow: visible; }
.food-exp-figure text { fill: #64716f; font: 15px 'Segoe UI', 'Microsoft JhengHei', sans-serif; }
.food-exp-grid { fill: none; stroke: #d8ddd4; stroke-width: 1; }
.food-exp-curve { fill: none; stroke: #b9543a; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
.food-exp-baseline { fill: none; stroke: #84928d; stroke-width: 2; stroke-dasharray: 5 5; }
.food-exp-reference { fill: none; stroke: #929c90; stroke-width: 1.5; stroke-dasharray: 3 5; }
.food-exp-marker-guide { fill: none; stroke: #b9543a; stroke-opacity: .4; stroke-width: 1.5; stroke-dasharray: 3 4; }
.food-exp-caption { color: var(--exp-muted); font-size: 13px; margin: 6px 0 0; text-align: center; }
.food-exp-choice { display: flex; align-items: center; flex-wrap: wrap; gap: 10px 16px; margin: 0 0 19px; font-size: 13px; }
.food-exp-choice select { flex: 1; min-width: 140px; max-width: 260px; border: 1px solid #cfd6dc; border-radius: 8px; padding: 9px 10px; background: #fff; color: var(--exp-ink); font: inherit; }
.food-exp-control { margin: 0 0 20px; }
.food-exp-control-label { display: flex; justify-content: space-between; flex-wrap: wrap; align-items: baseline; gap: 5px 12px; font-size: 14px; }
.food-exp-control-label output { color: var(--exp-accent); font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
.food-experiment input[type=range] { display: block; width: 100%; height: 30px; margin: 5px 0 0; accent-color: var(--exp-accent); cursor: pointer; padding: 0; }
.food-exp-endpoints { display: flex; justify-content: space-between; color: var(--exp-muted); font-size: 13px; line-height: 1.3; }
.food-exp-observation { margin: 2px 0 23px; max-width: 48em; min-height: 3.3em; color: var(--exp-ink); font-size: 14px; }
.food-exp-details { margin: 0; border-top: 1px solid var(--exp-line); }
