.starch-structure-lab *, .starch-structure-lab *::before, .starch-structure-lab *::after { box-sizing:border-box; }
.starch-structure-lab .starch-structure-kicker { margin:0 0 8px; color:#14665d; font-size:13px; letter-spacing:.06em; }
.starch-structure-lab h2 { margin:0; font-size:25px; font-weight:550; line-height:1.5; }
.starch-structure-lab .starch-structure-boundary { margin:10px 0 24px; color:var(--muted,#53606d); font-size:13px; }
.starch-structure-tools { display:flex; align-items:end; justify-content:space-between; gap:12px 20px; flex-wrap:wrap; }
.starch-structure-lab label { display:block; min-width:0; font-size:13px; color:var(--muted,#53606d); }
.starch-structure-lab select { display:block; width:100%; max-width:100%; min-width:0; min-height:44px; margin-top:5px; padding:9px 32px 9px 12px; color:var(--ink,#1c2732); background:#fff; border:1px solid #cfd6dc; border-radius:8px; font:inherit; font-size:14px; }
.starch-structure-tools > span { color:var(--muted,#53606d); font-size:13px; }
.starch-structure-canvas { margin:16px 0 20px; border:1px solid #dfe4e8; border-radius:8px; background:#f6f7f8; }
.starch-structure-svg { display:block; width:100%; max-width:540px; height:auto; margin:auto; overflow:visible; }
.starch-edge { cursor:pointer; }
.starch-edge-line { stroke:#6b8065; stroke-width:3; }
.starch-edge-hit { fill:transparent; stroke:none; pointer-events:all; }
.starch-edge-focus { fill:#f8f5eb; stroke:#b9543a; stroke-width:2; opacity:0; pointer-events:none; }
.starch-edge[aria-pressed="true"] .starch-edge-line { stroke:var(--copper,#b9543a); stroke-width:5; }
.starch-edge[aria-pressed="true"] .starch-edge-focus { opacity:1; }
.starch-edge[data-cut="true"] .starch-edge-line { stroke:#b0b1a8; stroke-dasharray:3 6; stroke-width:2; }
.starch-edge-cut { stroke:#8d4c38; stroke-width:2; fill:none; display:none; pointer-events:none; }
.starch-edge[data-cut="true"] .starch-edge-cut { display:block; }
.starch-edge:focus-visible { outline:none; }
.starch-edge:focus-visible .starch-edge-hit { stroke:#a85139; stroke-width:2; stroke-dasharray:3 3; }
.starch-residue { pointer-events:none; }
.starch-residue circle { fill:#dfe8d9; stroke:#6b8065; stroke-width:1.2; }
.starch-residue text { text-anchor:middle; fill:#2b4035; font-size:12px; font-family:inherit; }
.starch-residue[data-fragment="1"] circle { fill:#eadcca; stroke:#8a7051; }
.starch-residue[data-fragment="2"] circle { fill:#e0e7e9; stroke:#647e86; }
.starch-residue[data-fragment="3"] circle { fill:#e9dfe7; stroke:#8e7188; }
.starch-bond-choice { min-width:0; }
.starch-bond-choice select { width:100%; }
