.starch-structure-detail-body { padding-top:16px; font-size:14px; overflow-wrap:anywhere; }
.starch-structure-detail-body p { margin:0 0 16px; }
.starch-structure-lab .starch-equation { font-size:18px; line-height:2; color:#14665d; }
.starch-equation-block { padding:0 0 21px; overflow-wrap:anywhere; }
.starch-equation-block p { margin:0; }
.starch-structure-lab .starch-water { margin-top:6px; font-size:13px; color:var(--muted,#53606d); }
.starch-structure-lab sub { font-size:.72em; }
.starch-table-scroll { max-width:100%; overflow:auto; margin:12px 0 20px; }
.starch-structure-lab table { width:100%; border-collapse:collapse; font-size:13px; text-align:left; font-variant-numeric:tabular-nums; }
.starch-structure-lab th,.starch-structure-lab td { padding:8px 10px; border-bottom:1px solid #dfe4e8; }
.starch-structure-lab th { font-weight:550; }
.starch-fragment-formulas { padding:0; list-style:none; }
.starch-fragment-formulas li { display:flex; justify-content:space-between; gap:10px; flex-wrap:wrap; margin:8px 0; }
.starch-fragment-formulas strong { font-weight:500; }
.starch-fragment-formulas span { font-size:13px; color:var(--muted,#53606d); }
.starch-structure-detail-body > ul:not(.starch-fragment-formulas) { padding-left:19px; }
.starch-structure-detail-body li > span { display:block; color:var(--muted,#53606d); font-size:13px; }
.starch-structure-lab .starch-structure-note { font-size:13px; color:var(--muted,#53606d); }
.starch-structure-lab .starch-open-3d { display:block; margin:6px 0 20px; border:0; background:transparent; padding-left:0; text-align:left; color:#14665d; }
.starch-structure-lab :is(button,select,summary,a,[tabindex="0"]):focus-visible { outline:2px solid var(--copper,#14665d); outline-offset:3px; }
.starch-structure-lab .starch-edge:focus-visible { outline:none; }
@media(max-width:560px) {
 .starch-structure-lab h2 { font-size:21px; }
 .starch-structure-tools { display:block; }
 .starch-structure-tools > span { display:block; margin-top:12px; }
 .starch-structure-lab .starch-selected-bond { font-size:16px; }
 .starch-structure-lab button { padding:9px 12px; }
 .starch-structure-actions { gap:8px; }
 .starch-structure-lab .starch-equation { font-size:16px; }
}
@container(min-width:730px) {
 .starch-structure-workspace { display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:start;gap:28px;margin-top:24px; }
 .starch-structure-canvas { margin:0; }
 .starch-structure-actions { gap:6px; }
 .starch-structure-lab button { padding:9px 11px; }
 .starch-structure-lab .starch-selected-bond { font-size:16px; }
 .starch-structure-lab .starch-equation { font-size:16px; }
}

