.fa-progress-count { color:var(--fa-muted);font-size:16px;white-space:nowrap;padding-bottom:10px; }
.fa-current-case { margin:-8px 0 24px;font-size:16px;color:var(--fa-ink);overflow-wrap:anywhere; }
.fa-stage { margin:0 0 24px; }
.food-analysis-lab h3 { font-size:20px;line-height:1.6;margin:0 0 14px;font-weight:550;scroll-margin-top:100px; }
.fa-question { font-size:16px;margin:0 0 18px; }
.fa-fields { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px; }
.fa-readings { display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:22px 0; }
