.fa-reading small { display:block;color:var(--fa-muted);font-size:16px; }
.fa-equation-box { border-left:3px solid #cfd6dc;padding:12px 17px;margin:19px 0 22px;background:#f1f3f5; }
.food-analysis-lab .fa-equation { margin:0;font-size:17px;line-height:1.9;overflow-wrap:anywhere;font-variant-numeric:tabular-nums; }
.fa-current-caption { margin:7px 0 0;font-size:16px;color:var(--fa-muted); }
.fa-choice-row,.fa-actions { display:flex;flex-wrap:wrap;gap:10px;margin:16px 0; }
.food-analysis-lab button { min-height:44px;border:1px solid #cfd6dc;border-radius:8px;padding:9px 14px;color:#1c2732;background:#f1f3f5;font:inherit;font-size:16px;cursor:pointer; }
.food-analysis-lab button[aria-pressed="true"] { border:2px solid #14665d;padding:8px 13px;background:#e7f1ee;color:#14665d; }
.food-analysis-lab button.fa-primary { color:#fff;background:#14665d;border-color:#14665d; }
.food-analysis-lab button.fa-text { background:transparent;border-color:transparent;color:var(--fa-accent);text-decoration:underline;text-underline-offset:4px; }
.food-analysis-lab button:disabled { opacity:.5;cursor:default; }
.food-analysis-lab .fa-feedback { min-height:1.75em;margin:12px 0;color:var(--fa-accent);font-size:16px; }
