.fa-result > span { display:block;color:var(--fa-muted);font-size:16px; }
.fa-result > strong { display:block;font-size:34px;font-weight:500;color:#14665d;font-variant-numeric:tabular-nums;overflow-wrap:anywhere; }
.fa-result > small { font-size:16px;color:var(--fa-muted); }
.fa-result[data-valid="false"] { background:#f1f3f5;border-color:#d7c4b4; }
.fa-result[data-valid="false"] > strong { color:#7e4e38; }
