.fermentation-comparison-design h4 { color: var(--fcd-ink); line-height: 1.35; margin: 0 0 12px; }
.fermentation-comparison-design h3 { font-size: 20px; font-weight: 650; }
.fermentation-comparison-design h4 { font-size: 17px; font-weight: 650; }
.fermentation-comparison-design p { margin: 8px 0 14px; }
.fermentation-comparison-design small { display: block; font-size: 16px; color: var(--fcd-muted); }
.fermentation-comparison-design .fcd-muted { color: var(--fcd-muted); }
