/* ==== heterocycle-origin-lab.css ==== */
/* Heteroatom-origin workbench: precursor chips on the left, three ring verdicts on the right. */
.heterocycle-lab { --hc-ink: var(--ink, #1c2732); --hc-muted: var(--muted, #53606d); --hc-line: var(--line, #dfe4e8); --hc-accent: var(--mint, #14665d); color: var(--hc-ink); font-size: 1rem; line-height: 1.7; }
.heterocycle-lab [hidden] { display: none !important; }
.hc-head { margin-bottom: 18px; }
