.hc-chip span { display: grid; min-width: 0; }
.hc-chip small { color: var(--hc-muted); font-size: .875rem; }
.hc-rings { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; min-width: 0; }
