.hc-impossible .hc-badge { background: #eceff2; color: #4b5560; }
.hc-unverified { border-color: #e2cf97; }
.hc-unverified .hc-ring { color: #9a7417; }
.hc-unverified .hc-badge { background: #fbf3d9; color: #6f5310; }
.hc-carriers { margin: 0 0 6px; font-weight: 600; font-size: .9375rem; }
.hc-note { margin: 0; color: #2a3642; font-size: .9375rem; }
.hc-cite { margin: 8px 0 0; font-size: .875rem; color: var(--hc-muted); }
.heterocycle-lab a { color: var(--hc-accent); text-decoration: underline; text-underline-offset: 3px; }
.hc-rule { margin: 14px 0 26px; padding: 12px 16px; border-left: 4px solid var(--hc-accent); border-radius: 0 10px 10px 0; background: var(--chrome, #f6f7f8); color: #2a3642; font-size: .9375rem; }
.hc-process { padding: 18px 20px; border: 1px solid var(--hc-line); border-radius: 12px; }
.hc-process-head { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px 20px; }
