.hc-select select { min-height: 44px; min-width: 260px; max-width: 100%; padding: 8px 12px; border: 1px solid #cfd6dc; border-radius: 10px; background-color: #fff; font: inherit; color: inherit; }
.hc-points { margin: 14px 0 0; padding: 0; list-style: none; display: grid; gap: 10px; }
.hc-points li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 12px; align-items: baseline; }
.hc-tag { padding: 1px 10px; border-radius: 12px; background: var(--panel2, #f1f3f5); color: var(--hc-muted); font-size: .8125rem; font-weight: 600; white-space: nowrap; }
.hc-src { font-size: .875rem; }
.hc-boundary { margin: 12px 0 0; color: var(--hc-muted); font-size: .875rem; }
.heterocycle-lab details { margin-top: 0; padding: 4px 0; border-top: 1px solid var(--hc-line); }
.heterocycle-lab details:first-of-type { margin-top: 22px; }
