/* ==== radical-ledger-lab.css ==== */
/* Radical ledger: reaction buttons on the left, live species ledger on the right. */
.radical-lab { --rl-ink: var(--ink, #1c2732); --rl-muted: var(--muted, #53606d); --rl-line: var(--line, #dfe4e8); --rl-accent: var(--mint, #14665d); color: var(--rl-ink); font-size: 1rem; line-height: 1.7; }
.rl-head { margin-bottom: 16px; }
.rl-kicker { margin: 0; color: var(--rl-accent); font-size: .8125rem; font-weight: 600; letter-spacing: .08em; }
