.rl-hint { margin: 0; color: var(--rl-muted); }
.rl-setup { display: flex; flex-wrap: wrap; gap: 8px 10px; margin: 0 0 18px; padding: 0; border: 0; }
.rl-setup legend { margin-bottom: 8px; padding: 0; font-weight: 600; font-size: .9375rem; }
.rl-toggle { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 6px 14px; border: 1px solid #cfd6dc; border-radius: 22px; background: #fff; cursor: pointer; }
