.rl-reaction:hover:not(:disabled) { background: var(--chrome, #f6f7f8); border-color: #a9bcb8; }
.rl-reaction:disabled { opacity: .5; cursor: not-allowed; }
.rl-eq { font-family: 'Cambria Math', Cambria, var(--font, sans-serif); font-size: 1.0625rem; font-weight: 600; }
