.rl-ledger th small { margin-left: 8px; color: var(--rl-muted); font: 400 .8125rem var(--font, sans-serif); }
.rl-ledger td { padding: 4px 0; text-align: right; font-weight: 650; font-size: 1.0625rem; }
.rl-ledger tr + tr { border-top: 1px solid #eef1f3; }
.rl-ledger tr.rl-rad td { color: #a2531f; }
.rl-ledger tr.rl-zero td, .rl-ledger tr.rl-zero th { color: #a3adb7; }
.rl-sum { margin: 10px 0 0; padding-top: 8px; border-top: 1px solid var(--rl-line); font-size: .9375rem; }
.rl-actions { display: flex; gap: 8px; margin: 10px 0; }
.rl-actions button { flex: 1; min-height: 44px; border: 1px solid #cfd6dc; border-radius: 10px; background: #fff; font: inherit; cursor: pointer; }
