.rl-findings .rl-empty { color: #3f6259; }
.radical-lab details { padding: 4px 0; border-top: 1px solid var(--rl-line); }
.radical-lab details:first-of-type { margin-top: 18px; }
.radical-lab summary { min-height: 48px; padding: 12px 0; font-size: .9375rem; color: var(--rl-muted); }
.radical-lab details[open] > summary { color: var(--rl-ink); }
.radical-lab details p, .radical-lab details li { font-size: .9375rem; }
.radical-lab a { color: var(--rl-accent); text-decoration: underline; text-underline-offset: 3px; }
.rl-detail label { display: block; margin: 4px 0 6px; font-weight: 600; font-size: .9375rem; }
.rl-detail textarea { display: block; width: 100%; box-sizing: border-box; padding: 10px 14px; border: 1px solid #cfd6dc; border-radius: 10px; font: inherit; line-height: 1.8; resize: vertical; }
.rl-save { display: flex; align-items: center; flex-wrap: wrap; gap: 8px 14px; margin: 12px 0 14px; }
.rl-save button { min-height: 44px; padding: 8px 18px; border: 1px solid var(--rl-accent); border-radius: 10px; background: var(--rl-accent); color: #fff; font: inherit; font-weight: 600; cursor: pointer; }
