/* ==== extrusion-lab.css ==== */
.extrusion-lab { --ex-ink:#1c2732;--ex-muted:#53606d;--ex-line:#dfe4e8;--ex-a:#a04b2d;--ex-b:#286b7d;color:var(--ex-ink);font-size:16px;line-height:1.65;width:100%;max-width:1140px;min-width:0;margin:0 auto; }
.extrusion-lab *,.extrusion-lab *::before,.extrusion-lab *::after { box-sizing:border-box; }
.extrusion-lab [hidden] { display:none!important; }
.extrusion-lab h2 { font-size:23px;font-weight:550;line-height:1.45;margin:0; }
.extrusion-lab h3 { font-size:18px;font-weight:550;line-height:1.5;margin:0 0 10px; }
.extrusion-lab p { margin:8px 0 12px; }
.ex-header { display:flex;align-items:baseline;flex-wrap:wrap;gap:4px 18px;margin-bottom:12px; }
.ex-header p { font-size:16px;color:var(--ex-muted);margin:0; }
.extrusion-lab button { color:var(--ex-ink);background:#f1f3f5;border:1px solid #cfd6dc;border-radius:8px;min-height:44px;max-width:100%;padding:8px 13px;font:inherit;font-size:16px;line-height:1.5;cursor:pointer; }
.extrusion-lab button[aria-pressed="true"] { border-color:#14665d;box-shadow:inset 0 0 0 1px #14665d;background:#e7f1ee;color:#14665d; }
.extrusion-lab button:disabled { opacity:.5;cursor:default; }
.extrusion-lab button.ex-primary { background:#14665d;border-color:#14665d;color:#fff; }
.extrusion-lab label { display:block;font-size:16px;color:var(--ex-muted);min-width:0; }
.extrusion-lab :is(select,textarea) { width:100%;min-width:0;max-width:100%;min-height:44px;margin:5px 0 0;padding:8px 10px;color:var(--ex-ink);background:#fff;border:1px solid #cfd6dc;border-radius:8px;font:inherit;font-size:16px; }
.extrusion-lab textarea { display:block;resize:vertical;min-height:120px;line-height:1.65; }
.extrusion-lab textarea[readonly] { background:#f6f7f8; }
.ex-tabs { display:flex;gap:10px;margin:0 0 18px;border-bottom:1px solid var(--ex-line);padding-bottom:12px; }
.ex-tabs button { flex:1; }
.ex-flow-grid { display:grid;grid-template-columns:minmax(0,1.65fr) minmax(260px,1fr);gap:24px;align-items:start; }
.ex-flow { display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:13px;align-items:stretch; }
.ex-flow button { position:relative;display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:8px;text-align:center;padding:12px 8px; }
.ex-flow button:not(:last-child)::after { content:'→';position:absolute;right:-14px;top:43px;color:var(--ex-muted);font-size:18px; }
.ex-flow svg { width:64px;height:64px;max-width:100%;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round; }
.ex-flow .ex-study-step { border-style:dashed;background:#f6f7f8; }
.ex-flow small { font-size:16px; }
.ex-step-reading { border-left:3px solid #cfd6dc;background:#f1f3f5;padding:16px 18px;margin:14px 0; }
.ex-use { border-left:1px solid var(--ex-line);padding-left:22px; }
.ex-use h3 { margin-top:18px; }
.extrusion-lab .ex-caption { color:var(--ex-muted);font-size:16px;line-height:1.65; }
.ex-inline-sources { font-size:16px; }
.ex-controls { display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:14px; }
.ex-comparison-grid { display:grid;grid-template-columns:minmax(0,1.8fr) minmax(300px,1fr);gap:24px;align-items:start; }
.ex-plot-column,.ex-pair { min-width:0; }
.ex-plot-heading { display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 12px; }
.ex-plot-heading h3 { margin-bottom:0; }
