.sugar-chair-lab{width:100%;max-width:1060px;min-width:0;margin:0 auto;color:var(--ink);container-type:inline-size}
.sugar-chair-lab *{box-sizing:border-box}
.sc-header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:12px}
.sc-heading{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.sc-header-context{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.sc-model-identity{font-size:13px;color:var(--muted)}
.sc-kicker{margin:0 0 4px;color:var(--copper);font-size:13px}
.sugar-chair-lab h2{margin:0;font-size:28px;font-weight:550}
.sc-molecule-controls{display:flex;gap:10px;flex-wrap:wrap}
.sc-molecule-controls label{display:flex;align-items:center;gap:6px;white-space:nowrap}
.sugar-chair-lab .sc-molecule-controls select{margin-top:0}
.sugar-chair-lab label{font-size:13px;color:var(--muted)}
.sugar-chair-lab select{display:block;margin-top:4px;max-width:100%;font:inherit;font-size:14px;min-height:44px}
.sugar-chair-lab button{min-height:44px;padding:9px 14px;font:inherit;font-size:14px;cursor:pointer}
.sugar-chair-lab button[aria-pressed=true]{background:var(--ink);border-color:var(--ink);color:var(--panel)}
.sugar-chair-lab .button-primary{background:var(--copper);border-color:var(--copper);color:var(--panel)}
.sc-steps{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;padding-bottom:12px;border-bottom:1px solid var(--line)}
.sc-steps button{padding:9px 5px;white-space:nowrap}
.sc-steps button span{display:inline-block;margin-right:6px;opacity:.6;font-size:13px}
.sc-current{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:12px 0}
.sc-current-copy{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;min-width:0}
.sc-current h3{margin:0;font-size:21px;font-weight:550}
.sc-current-copy>span{font-size:13px;color:var(--muted)}
.sc-local-controls,.sc-view-tools{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0}
.sc-local-controls fieldset{display:flex;gap:5px;border:0;padding:0;margin:0;align-items:center}
.sc-local-controls legend{float:left;margin-right:6px;padding:0;font-size:13px;color:var(--muted)}
.sc-local-controls button{min-width:48px}
.sc-local-controls label{display:flex;align-items:center;gap:6px;margin-left:auto}
.sc-view-tools button{font-size:13px}
.sc-diagrams{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:12px 0;background:var(--panel2);border-radius:10px;padding:12px}
.sc-diagrams.sc-single{grid-template-columns:minmax(0,1fr)}
.sc-diagrams figure{margin:0;min-width:0}
.sc-diagrams figcaption{font-size:13px;color:var(--muted);text-align:center;margin:4px 0 0}
