.sc-single svg{max-width:430px}
.sc-bond{stroke:var(--ink);stroke-width:2;fill:none;stroke-linecap:round}
.sc-substituent{stroke:var(--blue);stroke-width:2;fill:none}
.sc-hydrogen{stroke:var(--muted);stroke-width:1.4;opacity:.65;fill:none}
.sc-label,.sc-carbon-label{fill:var(--ink);font-size:17px;paint-order:stroke;stroke:var(--panel2);stroke-width:4px;stroke-linejoin:round}
.sc-oxygen{fill:var(--copper);color:var(--copper)}
