@container(max-width:720px){.sc-spatial-workspace{grid-template-columns:minmax(0,1fr)}.sc-space-model{grid-row:1}.sc-space-canvas{height:340px}#sc-space-reference svg{max-width:360px;margin:12px auto}.sc-space-paper{padding:10px}}
