/* ==== colloid-experiments.css ==== */
/* Lesson-sized Stokes comparison; shared tokens and controls come from food-experiments.css. */
.colloid-experiment { container-type: inline-size; max-width: 900px; }
.colloid-experiment .colloid-boundary { margin: -4px 0 22px; padding-left: 12px; border-left: 2px solid var(--exp-line); color: var(--exp-muted); font-size: 13px; line-height: 1.75; }
.colloid-experiment .colloid-layout, .colloid-experiment .colloid-panel { min-width: 0; }
.colloid-experiment .colloid-stage { position: static; top: auto; padding: 15px 8px 16px; }
.colloid-experiment .colloid-panel > .food-exp-result { display: block; margin-bottom: 23px; }
.colloid-experiment .colloid-value { display: block; font-size: clamp(27px, 3vw, 38px); }
.colloid-experiment .colloid-direction { display: block; margin-top: 5px; }
.colloid-experiment .colloid-legend { display: flex; flex-wrap: wrap; justify-content: center; gap: 5px 15px; margin: 14px 0 9px; font-size: 13px; color: var(--exp-muted); }
.colloid-experiment .colloid-legend span { display: inline-flex; align-items: center; gap: 7px; }
.colloid-experiment .colloid-legend span::before { content: ''; flex-shrink: 0; width: 20px; border-top: 3px solid var(--exp-accent); }
.colloid-experiment .colloid-legend .colloid-reference::before { border-top: 2px dashed #cfd6dc; }
.colloid-experiment .colloid-formula { margin: 15px 6px 12px; padding-top: 12px; border-top: 1px solid var(--exp-line); font: 16px/1.8 'Cambria Math', 'Segoe UI', sans-serif; text-align: center; overflow-wrap: anywhere; }
.colloid-experiment .colloid-formula small { display: block; margin-top: 5px; color: var(--exp-muted); font: 13px/1.7 'Segoe UI', sans-serif; }
.colloid-experiment .colloid-readings { display: grid; gap: 9px; margin: 0 0 18px; padding-top: 13px; border-top: 1px solid var(--exp-line); font-size: 13px; }
.colloid-experiment .colloid-readings > div { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 3px 10px; }
.colloid-experiment .colloid-readings dt { color: var(--exp-muted); }
.colloid-experiment .colloid-readings dd { margin: 0; font-variant-numeric: tabular-nums; }
.colloid-experiment .colloid-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 21px; }
.colloid-experiment .colloid-actions button { flex: 1; padding: 8px 10px; border: 1px solid #cfd6dc; border-radius: 8px; background: transparent; color: var(--exp-muted); font: inherit; font-size: 13px; cursor: pointer; }
.colloid-experiment .colloid-actions button:hover { color: var(--exp-accent); border-color: var(--exp-accent); }
.colloid-experiment .colloid-actions button:disabled { opacity: .45; cursor: default; }
.colloid-experiment .colloid-actions button:focus-visible { outline: 3px solid var(--exp-accent); outline-offset: 3px; }
.colloid-experiment .colloid-observation { font-size: 13px; min-height: 0; }
.colloid-experiment .food-exp-equation { font-size: 14px; }
.colloid-experiment .food-exp-figure text { font-size: 14px; }
.colloid-experiment .food-exp-figure .colloid-svg-small { font-size: 12px; }
@container (min-width: 620px) {
  .colloid-experiment .colloid-layout { display: grid; grid-template-columns: minmax(0,1.15fr) minmax(0,1fr); gap: 25px; align-items: start; }
  .colloid-experiment .colloid-stage { position: sticky; top: 96px; margin-bottom: 0; }
  .colloid-experiment .colloid-panel > .food-exp-result { min-height: 78px; }
  .colloid-experiment .food-exp-control-label { font-size: 13px; }
}
@media (max-width: 480px) {
  .colloid-experiment .colloid-stage { position: static; top: auto; padding-inline: 3px; }
  .colloid-experiment .colloid-panel > .food-exp-result { padding-inline: 0; }
}

