.amino-range-labels { display:flex; justify-content:space-between; font-size:13px; color:#687480; }
.amino-shortcuts { display:flex; align-items:center; gap:12px; margin-top:17px; flex-wrap:wrap; }
.amino-shortcuts button,.amino-pka-shortcuts button { border:1px solid #cfd6dc; border-radius:8px; padding:8px 11px; color:#53606d; font-size:13px; background:#f6f7f8; }
.amino-shortcuts span { font-size:13px; color:#687480; }
.amino-mean { margin:29px 0 24px; }
.amino-mean>span { display:block; font-size:13px; color:#687480; }
