.amino-mean small { font-size:13px; color:#687480; }
.amino-fraction-heading { display:flex; align-items:center; justify-content:space-between; font-size:13px; color:#687480; gap:10px; }
.amino-fraction-heading button { font-size:13px; border:0; border-bottom:1px solid #cfd6dc; padding:5px 0; color:#687480; background:none; }
.amino-fraction-heading button[aria-pressed=true] { color:#14665d; border-color:#14665d; }
.amino-fractions { display:flex; flex-direction:column; gap:4px; margin:10px 0 8px; }
.amino-fractions button { display:flex; align-items:center; gap:10px; width:100%; border:1px solid transparent; border-radius:8px; background:transparent; padding:9px 8px; color:var(--amino-state); }
.amino-fractions button[aria-pressed=true] { background:#e7f1ee; border-color:#dce5d5; }
.amino-state-charge { font:17px Georgia,serif; width:25px; flex-shrink:0; text-align:center; }
.amino-fraction-track { display:block; flex:1; height:7px; background:#f1f3f5; border-radius:5px; overflow:hidden; }
.amino-fraction-track>span { display:block; height:100%; background:var(--amino-state); border-radius:5px; }
.amino-fraction-value { width:52px; font-size:13px; text-align:right; font-variant-numeric:tabular-nums; }
