.amino-follow-note { color:#687480; line-height:1.8; margin:5px 0 0; }
.amino-equation-panel { border-top:1px solid #dfe4e8; border-bottom:1px solid #dfe4e8; padding:22px 0 19px; margin:28px 0 16px; }
.amino-equation-top { display:flex; align-items:center; justify-content:space-between; gap:15px; color:#687480; font-size:13px; }
.amino-equation-top button { padding:7px 0; color:#53606d; font-size:13px; border:0; border-bottom:1px solid #cfd6dc; background:none; }
.amino-equation-top button:disabled { color:#acb5a6; cursor:default; border-color:transparent; }
.amino-equation { display:flex; align-items:center; gap:12px; flex-wrap:wrap; color:#53606d; font:19px/1.9 'Cambria Math',Georgia,serif; margin:15px 0 10px; overflow-wrap:anywhere; }
.amino-equation>span { min-width:0; }
.amino-equilibrium-arrow { font-size:25px; color:#687480; }
.amino-note { color:#687480; font-size:13px; line-height:1.95; margin:10px 0; }
.amino-pka-shortcuts { display:flex; flex-wrap:wrap; gap:8px; margin:14px 0; }
.amino-curve svg { width:100%; height:auto; display:block; }
.amino-curve text { fill:#919e88; font-size:12px; }
.amino-axis { stroke:#d7e0cf; fill:none; }
.amino-charge-curve { stroke:#789d88; stroke-width:2; fill:none; }
.amino-pi-line { stroke:#b4bda2; stroke-dasharray:3 5; }
.amino-curve circle { fill:#557d64; stroke:#f5f8ed; stroke-width:2; }
.amino-math { font-size:17px; display:block; }
@container (min-width:680px) { .amino-layout { display:grid; grid-template-columns:minmax(0,1.35fr) minmax(0,1fr); gap:34px; align-items:start; }.amino-equilibrium { padding:12px 0 0; } }
@container (max-width:679px) { .amino-equilibrium { margin-top:25px; }.amino-viewer { height:290px; }.amino-kind { display:none; } }
@media (max-width:480px) { .amino-choice button { padding:9px 13px; }.amino-molecule-panel { padding:17px 13px 12px; }.amino-equation { font-size:17px; gap:5px; }.amino-equation-top { align-items:flex-start; }.amino-equation-top button { max-width:140px; text-align:right; padding-top:0; }.amino-pka-shortcuts button { font-size:13px; }.amino-curve text { font-size:16px; } }

/* ==== learning-subjects.css ==== */
.learning-subjects { display:flex; gap:26px; align-items:center; margin:0 0 20px; border-bottom:1px solid var(--line); font-size:13px; }
.learning-subjects a { padding:0 0 11px; margin-bottom:-1px; color:var(--muted); border-bottom:2px solid transparent; }
.learning-subjects a[aria-current=page] { color:var(--ink); border-bottom-color:var(--copper); font-weight:600; }
:is(.learning-processing,.learning-microbiology) .learning-topic-grid { grid-template-columns:repeat(3,minmax(0,1fr)); }
:is(.learning-processing,.learning-microbiology) .learning-topic-link { min-width:0; }
.learning-review-subject { color:var(--muted); font-size:13px; }
.learning-connections { border-top:1px solid var(--line); padding:14px 0; font-size:13px; color:var(--muted); }
.learning-connections summary { cursor:pointer; }
.learning-connections nav { display:flex; flex-wrap:wrap; gap:10px 25px; padding:13px 0 5px; }
.learning-connections nav a { color:var(--ink); }
.learning-connections nav a small { display:block; margin-bottom:3px; color:var(--muted); font-size:11px; }
.processing-overview { margin:0; border:1px solid #d5dbcd; border-radius:9px; background:linear-gradient(160deg,#eef0e5,#f7f6ed 70%); overflow:hidden; display:flex; flex-direction:column; }
.processing-overview-heading { padding:25px 28px 0; }
.processing-overview-heading span { display:block; font-size:10px; letter-spacing:.13em; color:#6f8076; }
.processing-overview-heading strong { display:block; font-size:17px; font-weight:550; margin-top:7px; }
.processing-overview svg { display:block; width:100%; height:300px; flex:1; min-height:240px; max-height:320px; }
.processing-overview svg text { font:13px 'Segoe UI',sans-serif; fill:#52655c; }
.processing-overview .processing-diagram-title, .processing-overview .processing-diagram-title text { font-size:15px; fill:#34483f; font-weight:600; }
.processing-overview .processing-diagram-number { font-size:24px; font-family:Georgia,serif; fill:#34483f; }
.processing-overview .processing-diagram-number text { font:inherit; fill:inherit; }
.processing-overview .processing-diagram-unit { font:11px 'Segoe UI',sans-serif; fill:#6a7d70; }
.processing-overview .processing-diagram-detail { font-size:12px; }
.processing-overview figcaption { margin:0 25px; padding:14px 0; border-top:1px solid #d5dbcd; font:14px/1.8 'Cambria Math','Segoe UI',sans-serif; color:#445c4e; text-align:center; }
.processing-overview figcaption small { display:block; font:11px/1.7 'Segoe UI',sans-serif; color:#6a7d70; }
.learning-studio .processing-overview > a { display:flex; justify-content:space-between; gap:15px; padding:17px 25px; border-top:1px solid #d5dbcd; font-size:13px; color:#365b46; }
.microbiology-overview { background:linear-gradient(155deg,#edf2ed,#f7f6ef 75%); }
.microbiology-overview .microbiology-generation text { font:23px Georgia,serif; fill:#365947; text-anchor:middle; }
.microbiology-overview .microbiology-generation-label text { font-size:12px; text-anchor:middle; }
.processing-overview > a:hover { background:#e2e8d8; }
@media(max-width:1000px) {:is(.learning-processing,.learning-microbiology) .learning-topic-grid {grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:850px) { .learning-microbiology .learning-hero h1 br { display:initial; } }
@media(max-width:650px) {
  .learning-subjects { gap:24px; margin-bottom:15px; }
  :is(.learning-processing,.learning-microbiology) .learning-topic-grid { grid-template-columns:1fr; }
  .processing-overview-heading { padding:21px 22px 0; }
  .processing-overview svg { height:auto; min-height:215px; max-height:none; }
  .learning-topline { flex-wrap:wrap; row-gap:5px; }
}

/* ==== lipid-atlas.css ==== */
.lipid-atlas{--la-ink:#1c2732;--la-muted:#53606d;--la-line:#dfe4e8;--la-paper:#fff;max-width:900px;margin:0 auto;color:var(--la-ink);font-size:15px;line-height:1.75;overflow-wrap:anywhere}
.lipid-atlas *{box-sizing:border-box;min-width:0}
.lipid-atlas [hidden]{display:none!important}
.lipid-atlas p{margin:.5rem 0}
.lipid-atlas .la-header{margin-bottom:20px}
.lipid-atlas .la-kicker{font-size:13px;letter-spacing:.11em;color:#14665d;margin:0 0 5px}
.lipid-atlas .la-header h2{font-size:26px;line-height:1.45;font-weight:600;margin:4px 0 9px}
.lipid-atlas .la-intro,.lipid-atlas .la-muted{color:var(--la-muted);font-size:13px}
.lipid-atlas .la-views{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin:0 0 22px}
.lipid-atlas button{font:inherit;line-height:1.5;min-height:44px;padding:9px 12px;border:1px solid #cfd6dc;border-radius:8px;color:var(--la-ink);background:#f6f7f8;white-space:normal;cursor:pointer}
.lipid-atlas button:hover:not(:disabled){background:#e9edf0}
.lipid-atlas button[aria-pressed=true]{background:#e7f1ee;border-color:#14665d;color:#14665d;box-shadow:inset 0 -2px #14665d}
.lipid-atlas .la-primary{background:#14665d;border-color:#14665d;color:#fff}
.lipid-atlas .la-primary:hover:not(:disabled){background:#0e4f48}
.lipid-atlas button:disabled{cursor:default;opacity:.65}
.lipid-atlas :is(button,select,textarea,a,summary):focus-visible{outline:3px solid #14665d;outline-offset:3px}
.lipid-atlas .la-selectors,.lipid-atlas .la-comparison{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.lipid-atlas .la-selectors{margin:16px 0 12px}
.lipid-atlas .la-field{display:block;font-size:13px;font-weight:550;margin:10px 0}
.lipid-atlas :is(select,textarea){display:block;width:100%;max-width:100%;min-height:44px;font:inherit;font-size:14px;color:var(--la-ink);background:#fff;border:1px solid #cfd6dc;border-radius:8px;padding:10px;margin-top:5px;box-shadow:none}
.lipid-atlas textarea{resize:vertical;line-height:1.7;font-weight:400}
.lipid-atlas .la-card{border:1px solid var(--la-line);border-radius:9px;padding:20px;background:var(--la-paper)}
.lipid-atlas .la-card>header{display:flex;gap:12px;align-items:flex-start;min-height:70px}
.lipid-atlas .la-letter{flex:0 0 28px;display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#e9edf0;font-size:13px;color:#53606d;margin-top:4px}
.lipid-atlas h3{font-size:20px;font-weight:600;line-height:1.45;margin:0}
.lipid-atlas .la-english{font-size:13px;color:var(--la-muted);margin:3px 0}
.lipid-atlas .la-structure{margin:14px 0 18px;padding:15px;background:#f1f3f5;border-radius:6px;border-left:3px solid #c39c65}
.lipid-atlas figcaption{font-size:13px;color:var(--la-muted);letter-spacing:.04em;margin-bottom:5px}
.lipid-atlas .la-structure strong{font-size:20px;line-height:1.5;display:block;font-weight:550}
.lipid-atlas .la-structure p{font-size:13px;line-height:1.75}
.lipid-atlas dl{margin:0}
.lipid-atlas dt{font-size:13px;color:#7c5137;margin:15px 0 5px;font-weight:600}
.lipid-atlas dd{margin:0;font-size:14px;line-height:1.85}
.lipid-atlas details{border-top:1px solid var(--la-line);margin-top:20px;padding-top:5px}
.lipid-atlas summary{cursor:pointer;font-size:14px;font-weight:550;min-height:44px;padding:10px 0;line-height:1.8}
.lipid-atlas details>p,.lipid-atlas details>ul{font-size:13px}
.lipid-atlas .la-reaction-links{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0 4px}
.lipid-atlas .la-reaction-links button{font-size:13px;padding:8px 10px}
.lipid-atlas .la-senses{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid var(--la-line);border-radius:7px;background:#f1f3f5}
.lipid-atlas .la-senses>div{padding:14px 16px}
.lipid-atlas .la-senses>div+div{border-left:1px solid var(--la-line)}
.lipid-atlas .la-senses strong{display:block;font-size:17px;font-weight:550}
.lipid-atlas .la-senses span{display:block;font-size:13px;color:var(--la-muted);margin-top:4px}
.lipid-atlas .la-flavor-note{font-size:13px;max-width:65em;margin:13px 0 20px}
.lipid-atlas .la-reaction-select{max-width:430px;margin-bottom:20px}
.lipid-atlas .la-reaction{padding:22px;border:1px solid var(--la-line);background:var(--la-paper);border-radius:9px}
.lipid-atlas .la-reaction-flow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;list-style:none;padding:0;margin:24px 0}
.lipid-atlas .la-reaction-flow li{border-top:3px solid #cfd6dc;padding-top:10px}
.lipid-atlas .la-reaction-flow li+li{border-color:#cba47b}
.lipid-atlas .la-reaction-flow li:last-child{border-color:#a78562}
.lipid-atlas .la-reaction-flow span{display:block;font-size:13px;color:var(--la-muted)}
.lipid-atlas .la-reaction-flow p{font-size:14px;line-height:1.8;margin-top:8px}
.lipid-atlas .la-equation{margin:15px 0;padding:17px;background:#f1f3f5;border-radius:6px}
.lipid-atlas .la-equation p{font-size:17px;line-height:1.85;white-space:pre-wrap}
.lipid-atlas .la-sensory-effect{margin:20px 0 10px}
.lipid-atlas h4{font-size:13px;font-weight:600;color:#7c5137;margin:0 0 7px}
.lipid-atlas .la-sensory-effect p{font-size:15px}
.lipid-atlas .la-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}
.lipid-atlas .la-status{font-size:13px;color:#7c5137}
.lipid-atlas .la-status:empty{display:none}
.lipid-atlas .la-sources ul{padding-left:20px;line-height:1.9}
.lipid-atlas a{color:#14665d;text-underline-offset:3px}
@media(max-width:640px){.lipid-atlas .la-comparison{grid-template-columns:minmax(0,1fr)}.lipid-atlas .la-selectors{gap:10px}.lipid-atlas .la-card{padding:17px}.lipid-atlas .la-card>header{min-height:0}.lipid-atlas .la-reaction-flow{grid-template-columns:minmax(0,1fr);gap:10px;margin:20px 0}.lipid-atlas .la-reaction-flow li{padding:8px 0}.lipid-atlas .la-reaction-flow p{margin:4px 0}.lipid-atlas .la-reaction{padding:17px}.lipid-atlas .la-header h2{font-size:22px}}
@media(max-width:420px){.lipid-atlas .la-views{grid-template-columns:repeat(2,minmax(0,1fr))}.lipid-atlas .la-senses{grid-template-columns:minmax(0,1fr)}.lipid-atlas .la-senses>div{padding:11px 14px;display:flex;align-items:baseline;gap:15px}.lipid-atlas .la-senses>div+div{border-left:0;border-top:1px solid var(--la-line)}.lipid-atlas .la-senses strong{flex-shrink:0}.lipid-atlas .la-senses span{margin:0}.lipid-atlas .la-equation{padding:12px}.lipid-atlas .la-equation p{font-size:15px}}

/* ==== lipid-sites.css ==== */
.lipid-sites { width:100%; max-width:740px; min-width:0; margin:0 auto; color:var(--ink,#1c2732); line-height:1.75; }
.lipid-sites *, .lipid-sites *::before, .lipid-sites *::after { box-sizing:border-box; }
.lipid-sites-heading { margin-bottom:23px; }
.lipid-sites .lipid-sites-kicker { color:var(--copper,#14665d); font-size:13px; letter-spacing:.09em; margin:0 0 9px; }
.lipid-sites-heading h3 { font-size:24px; line-height:1.65; font-weight:550; margin:0; }
.lipid-pathway-tabs { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:0; border-bottom:1px solid var(--line,#dfe4e8); margin-bottom:22px; }
.lipid-pathway-tabs button { min-height:69px; padding:10px 12px; background:transparent; border:0; border-bottom:3px solid transparent; border-radius:0; color:var(--muted,#53606d); text-align:left; }
.lipid-pathway-tabs button strong { display:block; font-size:16px; font-weight:550; }
.lipid-pathway-tabs button span { display:block; margin-top:2px; font-size:13px; }
.lipid-pathway-tabs button[aria-selected="true"] { border-bottom-color:var(--copper,#14665d); color:var(--ink,#14665d); background:#e7f1ee; }
.lipid-sites .lipid-sites-question { font-size:17px; margin:0 0 23px; }
.lipid-reference-title { display:flex; align-items:baseline; flex-wrap:wrap; justify-content:space-between; gap:5px 15px; margin-bottom:12px; }
.lipid-reference-title strong { font-size:14px; font-weight:550; }
.lipid-reference-title strong span { margin-left:6px; font-size:13px; color:var(--muted,#53606d); }
.lipid-reference-title > span { font-size:13px; color:var(--muted,#53606d); }
.lipid-carbon-grid { display:grid; grid-template-columns:repeat(9,minmax(0,1fr)); gap:8px; padding:0; }
.lipid-sites .lipid-carbon { min-width:44px; min-height:64px; padding:7px 2px 5px; margin:0; border:1px solid #dfe4e8; border-radius:5px; background:#fff; color:var(--ink,#1c2732); font-size:15px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:0; }
.lipid-carbon-number { line-height:1.6; font-variant-numeric:tabular-nums; }
.lipid-carbon-mark { display:block; min-height:18px; font-size:13px; line-height:18px; font-weight:700; }
.lipid-sites .lipid-carbon:hover { background:#f1f3f5; }
.lipid-sites .lipid-carbon[aria-pressed="true"] { border:2px solid var(--copper,#14665d); padding:6px 1px 4px; color:#994b34; background:#f9ecde; }
.lipid-sites .lipid-carbon[data-result="correct"] { background:#e7f1ee; border-color:#cfd6dc; color:#14665d; }
.lipid-sites .lipid-carbon[data-result="missing"] { border-style:dashed; border-color:#cfd6dc; background:#f6f7f8; color:#14665d; }
.lipid-sites .lipid-carbon[data-result="extra"] { border-color:#a3513a; color:#9b4531; }
.lipid-carbon[data-comparison="shared"] .lipid-carbon-mark { color:#14665d; }
.lipid-carbon[data-comparison="additional"] .lipid-carbon-mark { color:#b9543a; }
.lipid-sites .lipid-original-landmarks { display:flex; flex-wrap:wrap; gap:2px 16px; margin:12px 0 18px; color:var(--muted,#53606d); font-size:13px; }
.lipid-original-landmarks span { white-space:normal; }
.lipid-selection-row { display:flex; justify-content:space-between; align-items:baseline; gap:12px; min-height:36px; }
.lipid-selection-row p { font-size:13px; margin:0; overflow-wrap:anywhere; }
.lipid-sites .lipid-reset { flex-shrink:0; min-height:40px; padding:5px 0; border:0; background:transparent; color:var(--muted,#53606d); font-size:13px; text-decoration:underline; text-underline-offset:3px; }
.lipid-check-row { display:flex; justify-content:space-between; align-items:center; gap:15px; flex-wrap:wrap; margin:12px 0 0; }
.lipid-check-row .button-primary { min-height:44px; padding:10px 17px; font-size:14px; }
.lipid-compare-toggle { display:flex; align-items:center; gap:9px; color:var(--muted,#53606d); font-size:13px; cursor:pointer; min-height:44px; }
.lipid-compare-toggle input { margin:0; width:17px; height:17px; accent-color:#14665d; }
.lipid-sites .lipid-sites-feedback { margin:17px 0 23px; min-height:1.75em; color:#8e4b35; font-size:14px; line-height:1.85; }
.lipid-sites-feedback[data-correct="true"] { color:#14665d; }
.lipid-comparison { padding:18px 20px; margin:0 0 24px; border:1px solid #dfe4e8; border-radius:5px; background:#f1f3f5; }
.lipid-comparison[hidden] { display:none; }
.lipid-comparison-key { display:flex; gap:8px 20px; flex-wrap:wrap; margin-bottom:15px; font-size:13px; }
.lipid-comparison-key span { display:flex; align-items:center; gap:7px; }
.lipid-site-dot { width:7px; height:7px; border-radius:50%; background:#34654b; }
.lipid-site-dot.additional { background:#b9543a; }
.lipid-comparison > p { display:flex; gap:18px; margin:7px 0; font-size:14px; }
.lipid-comparison > p strong { min-width:65px; font-weight:550; }
.lipid-comparison .lipid-comparison-note { display:block; font-size:13px; margin-top:17px; color:#53606d; }
.lipid-sites-details { border-top:1px solid var(--line,#dfe4e8); padding:16px 0; margin:0; }
.lipid-sites-details > summary { cursor:pointer; font-size:14px; color:var(--muted,#53606d); }
.lipid-mechanism-note { font-size:14px; line-height:1.85; padding-top:13px; }
.lipid-mechanism-note p { margin:0 0 14px; }
.lipid-mechanism-note small { display:block; color:var(--muted,#53606d); font-size:13px; margin:10px 0 20px; }
.lipid-mechanism-note .lipid-scheme { color:#14665d; padding:12px 14px; background:#f1f3f5; border-left:2px solid #cfd6dc; overflow-wrap:anywhere; font-size:17px; }
.lipid-mechanism-note ul { padding-left:20px; }
.lipid-mechanism-note li { margin:13px 0; overflow-wrap:anywhere; }
.lipid-mechanism-note li span { display:block; font-size:13px; color:var(--muted,#53606d); }
.lipid-sites button:focus-visible,.lipid-sites input:focus-visible,.lipid-sites summary:focus-visible,.lipid-sites a:focus-visible { outline:2px solid var(--copper,#14665d); outline-offset:3px; }
.lipid-sites button:disabled { opacity:.45; cursor:default; }
@media(max-width:620px) {
 .lipid-carbon-grid { grid-template-columns:repeat(6,minmax(0,1fr)); gap:6px; }
 .lipid-sites .lipid-carbon { min-height:60px; }
 .lipid-sites-heading h3 { font-size:21px; }
 .lipid-sites .lipid-sites-question { font-size:16px; }
 .lipid-pathway-tabs button { padding:10px; }
