#lactose-acid-arrows { margin:4px 0; padding-left:24px; }
#lactose-acid-charge { font-size:13px; color:#56645b; }
.lactose-acid-table-wrap { max-width:100%; overflow-x:auto; }
.lactose-acid-table-wrap table { width:100%; border-collapse:collapse; font-size:13px; }
