@media(max-width:640px) { #lactose-endpoint-canvas { height:350px; } .lactose-endpoint-controls > div { flex-direction:column; } .lactose-endpoint-camera button { font-size:12px; } }
.lactose-site-lab :is(button,select,textarea,summary,a):focus-visible, .lactose-site-original > summary:focus-visible { outline:3px solid #6c8751; outline-offset:3px; }
@media(max-width:850px) { .lactose-site-fields { grid-template-columns:1fr; gap:18px; } }
@media(max-width:640px) {
