/* Learning text can grow without a fixed-height header covering the lesson. */
body[data-surface=learn] .topbar { position:relative; height:auto; min-height:76px; box-sizing:border-box; flex-wrap:wrap; padding-top:8px; padding-bottom:8px; }
body[data-surface=learn] .topbar .brand { max-width:100%; }
body[data-surface=learn] .topbar .brand-wordmark { min-width:0; overflow-wrap:anywhere; }
body[data-surface=learn] .topbar .header-actions { min-width:0; max-width:100%; flex-wrap:wrap; }
body[data-surface=learn] .learning-context-bar { position:relative; top:auto; flex-wrap:wrap; }
@media(max-width:640px) { body[data-surface=learn] .topbar { min-height:67px; } }

/* One current-state cue, with view adjustments and identities on demand. */
.lactose-camera-details { margin:10px 0 14px; border-top:1px solid var(--line); }
.lactose-camera-details .lactose-endpoint-camera { margin:8px 0 12px; }
.lactose-observation-cue { margin:14px 0; padding:13px 17px; border-left:3px solid #6b8976; border-radius:0 6px 6px 0; background:#edf2e6; }
.lactose-observation-cue h3 { margin:0 0 7px; font-size:18px; line-height:1.6; }
.lactose-observation-cue p { margin:7px 0; }
#lactose-observation-question { font-weight:550; }
.lactose-scene-column { min-width:0; }
#lactose-label-warning { padding:10px 13px; margin:12px 0; border-left:3px solid #b98c5b; background:#f7eadb; }
.lactose-label-details { min-width:0; margin-top:8px; }
#lactose-label-reference { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,16em),1fr)); gap:10px; margin:13px 0; }
#lactose-label-reference > div { min-width:0; padding:11px 13px; border:1px solid #d7ddcf; border-radius:6px; background:#f4f5ec; }
#lactose-label-reference dt { white-space:nowrap; font-weight:600; }
#lactose-label-reference dd { margin:6px 0 0; line-height:1.8; overflow-wrap:anywhere; }

/* The four primary links keep their width when enlarged text needs two lines. */
body[data-surface=learn] .sidebar nav > .nav-item[data-learning] > .nav-label { min-width:0; white-space:normal; overflow-wrap:anywhere; }

/* ==== learning-paths.css ==== */
/* A reading itinerary: numbered questions, a quiet food sketch, one next stop. */
.skip-content { position:fixed; top:8px; left:16px; z-index:200; transform:translateY(-160%); padding:12px 20px; background:var(--panel); color:var(--ink); border:2px solid var(--copper); }
.skip-content:focus { transform:none; }
.path-heading { padding:24px 0 40px; max-width:900px; }
.path-heading h1 { font-size:clamp(32px,3.25vw,48px); line-height:1.4; letter-spacing:-.035em; margin:16px 0 18px; font-weight:650; }
.path-heading > p:last-child,.path-heading > div > p:last-child { color:var(--muted); font-size:16px; line-height:1.9; max-width:36em; }
.path-heading .learning-kicker,.path-reflection .learning-kicker { color:#52685b; }
.path-directory { border-top:1px solid var(--line); }
.path-directory-row { display:grid; grid-template-columns:38px 84px minmax(0,1fr) auto; gap:24px; align-items:center; padding:29px 0; border-bottom:1px solid var(--line); }
.path-number,.path-station-number,.path-entry-number { font-family:Georgia,'Times New Roman',serif; font-variant-numeric:tabular-nums; color:#566c5f; }
.path-number { font-size:28px; align-self:start; padding-top:6px; }
.path-drawing { display:block; width:84px; height:84px; color:#52685b; }
.path-meta { font-size:12px; color:var(--muted); line-height:1.7; }
.path-directory-copy h2 { font-size:23px; font-weight:560; margin:6px 0 9px; line-height:1.65; }
.path-directory-copy h2 span { color:var(--copper); font-size:16px; margin-left:6px; }
.path-directory-copy > p:last-child { font-size:14px; color:var(--muted); line-height:1.8; }
.path-open { display:inline-flex; align-items:center; gap:24px; min-height:44px; font-size:13px; white-space:nowrap; padding:6px 0; }
.path-footnote { font-size:12px; color:var(--muted); line-height:1.9; margin-top:27px !important; }
.path-overview-heading { display:flex; justify-content:space-between; gap:30px; align-items:center; padding-bottom:24px; }
.path-overview-heading .path-drawing { flex:0 0 110px; height:110px; width:110px; }
.path-overview-heading h1 { font-size:clamp(28px,2.8vw,38px); }
.path-start-row { display:flex; align-items:center; gap:24px; margin:0 0 34px; flex-wrap:wrap; }
.path-start-row > span { font-size:12px; color:var(--muted); }
.path-stations { list-style:none; padding:0; margin:0; max-width:900px; }
.path-stations > li { display:flex; position:relative; align-items:center; gap:26px; padding:23px 0; border-top:1px solid var(--line); }
.path-station-number { font-size:28px; min-width:36px; align-self:flex-start; }
.path-station-copy { flex:1; min-width:0; }
.path-station-copy h2 { font-size:19px; line-height:1.7; font-weight:550; margin:6px 0; }
.path-station-copy h2 a { display:block; padding:3px 0; }
.path-station-copy h2 a span { font-size:15px; white-space:nowrap; color:var(--copper); }
.path-lesson-title { font-size:12px; color:var(--muted); }
.path-answer-status { display:inline-block; margin-left:12px; color:#365d46; }
.path-answer-status:before { content:'· '; }
.path-answer-link { font-size:12px; padding:12px 0; flex-shrink:0; }
.path-reflection { max-width:900px; padding:26px 28px; margin:20px 0 23px; background:#e9ede4; border-left:3px solid #6b8976; }
.path-reflection h2 { font-size:20px; line-height:1.8; font-weight:550; margin:10px 0; max-width:34em; }
.path-reflection > p:last-child { font-size:13px; color:var(--muted); }
.path-boundary { max-width:900px; font-size:13px; line-height:1.9; color:var(--muted); margin:24px 0; }
.path-boundary summary { min-height:44px; padding:9px 0; }
.path-boundary p { margin:10px 0; }
.path-context { max-width:870px; padding:15px 20px; margin:0 0 20px; background:#e9ede4; border-left:3px solid #6b8976; }
.path-context > div { display:flex; flex-wrap:wrap; justify-content:space-between; align-items:baseline; gap:5px 15px; }
.path-context a { font-size:13px; font-weight:550; padding:6px 0; }
.path-context span,.path-context small { color:var(--muted); font-size:12px; }
.path-context p { color:#365447; font-size:14px; line-height:1.8; margin-top:5px; }
.path-storage-warning { color:var(--muted); font-size:13px; margin:12px 0 24px !important; }
.path-storage-warning a { text-decoration:underline; margin-left:8px; }
.path-next { margin-top:28px; }
.path-entry { padding:15px 0 0; }
.path-entry-list { border-top:1px solid var(--line); }
.path-entry-list > div { display:flex; align-items:center; gap:22px; padding:10px 0; border-bottom:1px solid var(--line); font-size:16px; }
.path-entry-list a { display:inline-flex; align-items:center; min-height:44px; }
.path-entry-list .path-entry-resume,.path-entry-count { margin-left:auto; font-size:12px; color:var(--muted); flex-shrink:0; }
.path-entry-number { font-size:20px; }
@media(max-width:1100px) {
  .path-directory-row { grid-template-columns:30px 64px minmax(0,1fr); gap:18px; }
  .path-directory-row .path-drawing { width:64px; height:64px; }
  .path-open { grid-column:3; justify-self:start; padding:0; margin-top:-14px; }
}
@media(max-width:600px) {
  .sidebar .nav-item[data-learning] { min-height:44px; }
  .learning-subjects a { min-height:44px; padding-top:7px; }
  .path-heading { padding:17px 0 28px; }
  .path-heading h1 { font-size:31px; margin:13px 0 18px; }
  .path-heading > p:last-child,.path-heading > div > p:last-child { font-size:15px; }
  .path-directory-row { grid-template-columns:32px minmax(0,1fr); gap:10px 14px; padding:23px 0; }
  .path-directory-row .path-drawing { grid-column:1; grid-row:2; width:36px; height:42px; align-self:start; }
  .path-number { grid-column:1; grid-row:1; font-size:25px; padding:0; }
  .path-directory-copy { grid-column:2; grid-row:1 / 3; }
  .path-directory-copy h2 { font-size:20px; margin:7px 0 10px; }
  .path-directory-copy > p:last-child { font-size:13px; }
  .path-meta { font-size:11px; }
  .path-open { grid-column:2; margin:0; }
  .path-overview-heading { gap:12px; align-items:flex-start; }
  .path-overview-heading h1 { font-size:28px; }
  .path-overview-heading .path-drawing { display:none; }
  .path-start-row { gap:13px; margin-bottom:26px; }
  .path-stations > li { gap:15px; flex-wrap:wrap; padding:21px 0; }
  .path-station-number { font-size:24px; min-width:29px; }
  .path-station-copy h2 { font-size:17px; }
  .path-answer-link { flex-basis:calc(100% - 44px); margin-left:44px; padding:5px 0; min-height:44px; }
  .path-reflection { padding:21px 20px; }
  .path-reflection h2 { font-size:18px; }
  .path-context { padding:11px 14px; }
  .path-context a { font-size:12px; min-height:44px; display:inline-flex; align-items:center; }
  .path-context p { font-size:13px; }
  .path-entry .learning-section-heading { gap:12px; flex-wrap:wrap; }
  .path-entry-list > div { font-size:15px; gap:15px; flex-wrap:wrap; }
  .path-entry-list .path-entry-resume { margin-left:37px; }
}

/* ==== study-roadmap.css ==== */
.study-roadmap { margin:0 0 38px; max-width:1120px; }
.study-roadmap h2,.study-core-intro h2 { font-size:24px; line-height:1.6; margin:0 0 14px; }
.study-roadmap p,.study-core-intro p,.study-core-intro li { max-width:65em; line-height:1.9; }
