.study-start { padding:20px 0; border-bottom:1px solid var(--line); }
.study-start h3 { font-size:20px; margin:4px 0 8px; }
.study-start p { margin:7px 0; }
.study-start-status { font-size:13px; color:var(--muted); }
.study-start-link { display:inline-flex; align-items:center; min-height:44px; text-decoration:underline; text-underline-offset:4px; }
.study-roadmap summary,.study-station-reasoning summary { padding:12px 0; min-height:44px; cursor:pointer; }
