.protein-path-lab p{margin:12px 0}.protein-path-lab label{display:block;margin:14px 0}.protein-path-lab select,.protein-path-lab input[type=text],.protein-path-lab textarea{font:inherit;max-width:100%;width:100%;padding:10px 12px;background:var(--panel,#fff);color:var(--ink,#1e3028);border:1px solid #87988c;border-radius:4px;line-height:1.65}
.protein-path-lab textarea{resize:vertical;white-space:pre-wrap}.protein-path-lab button{font:inherit;min-height:44px;padding:9px 16px;margin:6px 8px 6px 0}.protein-path-lab a{text-decoration:underline;text-underline-offset:3px}.protein-path-lab :focus-visible{outline:3px solid #a5562f;outline-offset:3px}
