.glc-fru-axis-labels { position: relative; height: 1.65em; margin: 0 8.5714285714%; color: var(--glc-fru-muted); font-size: .9375rem; line-height: 1.65; }
.glc-fru-axis-labels span { position: absolute; top: 0; transform: translateX(-50%); white-space: nowrap; font: inherit; }
.glc-fru-equilibrium-lab .glc-fru-axis-title { margin: 4px 10px 0; color: var(--glc-fru-muted); font-size: .875rem; line-height: 1.6; text-align: center; overflow-wrap: anywhere; }
