.glc-fru-equilibrium-lab .glc-fru-sources p, .glc-fru-equilibrium-lab .glc-fru-sources li { margin: 5px 0; font-size: .8125rem; line-height: 1.75; overflow-wrap: anywhere; }
.glc-fru-sources ol { margin: 12px 0; padding-left: 21px; }
.glc-fru-sources li { margin-bottom: 13px !important; }
.glc-fru-sources a { color: #14665d; text-underline-offset: 3px; }
.glc-fru-equilibrium-lab .glc-fru-sources .glc-fru-evidence-record { font-size: 0.8125rem; color: var(--glc-fru-muted); }
.glc-fru-source-table { overflow-x: auto; }
.glc-fru-source-table table { border-collapse: collapse; min-width: 400px; width: 100%; max-width: 600px; font-size: .8125rem; font-variant-numeric: tabular-nums; }
