/* ==== interface.css ==== */
/* Shared navigation and reading hierarchy. Scientific widgets keep their own layouts. */
:root {
  color-scheme: light;
  --font: 'Microsoft JhengHei UI', 'Microsoft JhengHei', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --bg: #f7f8fa;
  --panel: #ffffff;
  --panel2: #f0f3f5;
  --ink: #24313f;
  --muted: #617080;
  --faint: #6b7785;
  --line: #e3e8ed;
  --mint: #176b62;
  --copper: #176b62;
  --copper-soft: #eaf3f0;
  --radius: 12px;
  --shadow: none;
}

body { font-family: var(--font); font-size: 1rem; line-height: 1.75; }
a { text-underline-offset: 4px; }
h1, h2, h3 { letter-spacing: 0; }
button, input, select, textarea { font-family: inherit; }
button:hover { background: #edf3f1; border-color: #a9bcb8; }
:is(button, a, input, select, textarea, summary):focus-visible {
  outline: 3px solid #176b62;
  outline-offset: 3px;
}
[hidden] { display: none !important; }

/* One stable frame across the course directory, lessons, and exploration tools. */
.topbar, body[data-surface=learn] .topbar {
  position: relative;
  top: auto;
  min-height: 68px;
  height: auto;
  padding: 12px 28px;
  gap: 20px;
  background: #fff;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}
.brand { min-width: 0; max-width: 100%; gap: 12px; font-size: 1rem; letter-spacing: 0; }
.brand-mark { display: block; flex: 0 0 28px; width: 28px; height: 28px; color: var(--mint); }
.brand-wordmark { min-width: 0; line-height: 1.55; overflow-wrap: anywhere; }
.brand-subtitle, .brand small { font-size: .75rem; letter-spacing: 0; color: var(--muted); font-weight: 400; }
.header-actions { gap: 16px; min-width: 0; max-width: 100%; flex-wrap: wrap; }
.header-context, .header-note { font-size: .875rem; letter-spacing: 0; color: var(--muted); }
.save-status { font-size: .8125rem; }
.help-button { width: 36px; min-height: 36px; font: 1rem/1 var(--font); border-color: var(--line); background: #fff; }
.navigation-toggle { display: none; }
.workspace { display: grid; grid-template-columns: 220px minmax(0, 1fr); min-height: calc(100vh - 68px); }
.sidebar {
  position: sticky;
  top: 0;
  align-self: start;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 28px;
  min-width: 0;
  min-height: calc(100vh - 68px);
  padding: 32px 16px 24px;
  background: #fff;
  border-right: 1px solid var(--line);
  border-bottom: 0;
}
.sidebar nav { display: grid; flex: none; gap: 5px; overflow: visible; min-width: 0; }
.nav-caption, .nav-heading { display: block; margin: 0 12px 12px; padding: 0; font-size: .75rem; font-weight: 500; letter-spacing: 0; color: var(--muted); }
.sidebar > .nav-caption { margin-bottom: -20px; }
.nav-item, .sidebar .nav-item[data-learning] {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: flex-start;
  gap: 12px;
  width: 100%;
  min-width: 0;
  min-height: 46px;
  margin: 0;
  padding: 10px 12px;
  border: 0;
  border-radius: 7px;
  color: #536271;
  background: transparent;
  font-size: .9375rem;
  font-weight: 450;
  line-height: 1.65;
  text-align: left;
  white-space: normal;
}
.nav-item > .nav-label { display: block; flex: 1; min-width: 0; margin: 0; font: inherit; color: inherit; text-align: left; white-space: normal; overflow-wrap: anywhere; }
.nav-item > .nav-icon { display: inline-flex; flex: 0 0 19px; width: 19px; height: 19px; margin: 0; color: inherit; }
.nav-icon svg { width: 100%; height: 100%; }
.nav-item > .nav-number { display: inline-block; flex: 0 0 19px; width: 19px; margin: 0; font: .875rem/1 var(--font); color: inherit; }
.sidebar .nav-item:hover { background: #f3f6f7; color: var(--ink); }
.sidebar .nav-item.active, .sidebar .nav-item[aria-current=page] { background: #eaf3f0; color: #176b62; font-weight: 600; }
.nav-item.active > span { color: inherit; }
.nav-subjects { min-width: 0; }
.nav-subjects > summary { min-height: 44px; padding: 10px 12px; color: var(--muted); font-size: .875rem; cursor: pointer; }
.nav-subjects[open] > summary { color: var(--mint); }
.subject-nav { min-width: 0; padding-top: 4px; }
.subject-nav a { min-height: 42px; padding: 8px 12px; border-radius: 6px; font-size: .875rem; line-height: 1.7; color: var(--muted); }
.subject-nav a:hover { background: #f3f6f7; color: var(--ink); }
.subject-nav a[aria-current], .subject-nav a.active { background: #f0f5f3; color: #176b62; }
.sidebar .nav-tools { display: block; border-top: 0; margin: 0; padding: 0; min-width: 0; }
.nav-tools summary { padding: 10px 12px; min-height: 44px; font-size: .875rem; line-height: 1.7; color: var(--muted); }
.nav-tools summary:hover { color: var(--mint); }
.nav-tools[open] summary { margin-bottom: 7px; }
.nav-tools .nav-item { font-size: .875rem; min-height: 44px; }
.sidebar-bottom { display: block; margin-top: auto; padding: 16px 12px 0; }
.sidebar-bottom .text-button { min-height: 44px; padding: 8px 0; font-size: .8125rem; line-height: 1.65; color: var(--muted); white-space: normal; text-align: left; }
main, body[data-surface=learn] main { width: 100%; max-width: 1240px; min-width: 0; margin: 0 auto; padding: 28px 48px; }
.workspace-footer, body[data-surface=learn] .workspace-footer { flex-wrap: wrap; gap: 10px 24px; margin-top: 64px; padding-top: 20px; border-top: 1px solid var(--line); font-size: .75rem; line-height: 1.8; color: var(--muted); }
.page-heading h1 { font-size: 1.875rem; line-height: 1.5; }
.page-heading p { font-size: 1rem; max-width: 48em; }

/* The home page offers one search and three unmistakable starting points. */
.study-home { max-width: 1100px; }
.study-welcome { padding: 8px 0 26px; }
.learning-studio .study-welcome h1 { font-size: 1.875rem; font-weight: 650; line-height: 1.5; letter-spacing: 0; }
.learning-studio .study-welcome p { margin-top: 10px; max-width: 44em; font-size: 1rem; color: var(--muted); line-height: 1.85; }
.study-search {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  max-width: 760px;
  min-height: 58px;
  padding: 5px 6px 5px 18px;
  border: 1px solid #cdd6de;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 12px #24313f04;
}
.study-search:focus-within { border-color: #176b62; box-shadow: 0 0 0 3px #176b6212; }
.study-search > svg { flex: 0 0 20px; width: 20px; height: 20px; color: var(--muted); }
.study-search input:not([type=range]):not([type=checkbox]):not([type=file]) { flex: 1; min-width: 0; width: 100%; min-height: 44px; padding: 7px 0; border: 0; border-radius: 0; background: transparent; color: var(--ink); font: 1rem/1.75 var(--font); }
.study-search input::placeholder { color: #73808c; opacity: 1; }
.study-search input:focus-visible { outline: 0; }
.study-search button { flex: 0 0 auto; min-height: 44px; padding: 9px 18px; border: 0; border-radius: 6px; background: #176b62; color: #fff; font-size: .9375rem; }
.study-search button:hover { background: #11564f; }
.study-search-hints { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 18px; margin: 11px 0 0; color: var(--muted); font-size: .8125rem; }
.study-search-hints a { display: inline-flex; align-items: center; min-height: 32px; color: var(--muted); }
.study-search-hints a:hover { color: var(--mint); text-decoration: underline; }
.study-resume { display: flex; align-items: center; justify-content: space-between; gap: 24px; margin: 30px 0 40px; padding: 22px 26px; background: #edf4f1; border-radius: 10px; }
.study-resume > div { min-width: 0; }
.study-resume small { font-size: .8125rem; color: #496a60; }
.learning-studio .study-resume h2 { margin: 4px 0 2px; font-size: 1.125rem; line-height: 1.65; font-weight: 600; }
.study-resume p { font-size: .875rem; color: var(--muted); }
.study-resume .learning-primary { flex: 0 0 auto; }
.study-section-heading { margin: 34px 0 20px; }
.learning-studio .study-section-heading h2 { font-size: 1.25rem; font-weight: 600; line-height: 1.6; }
.learning-studio .study-section-heading p { margin-top: 4px; font-size: .875rem; color: var(--muted); }
.study-subject-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
