.exam-sketch button:disabled { opacity:.5;cursor:not-allowed; }
.exam-sketch :is(button,input,canvas):focus-visible { outline:3px solid #187766;outline-offset:3px; }
.exam-sketch [data-sketch-retry] { background:#fff4e6;color:#81440b;border-color:#d2aa70; }
.exam-sketch [hidden] { display:none!important; }
.exam-sketch .exam-sketch-frame { overflow:hidden;border:1px solid #bdcec0;border-top:0;border-radius:0 0 12px 12px;background:#fff; }
.exam-sketch canvas { display:block;width:100%;height:auto;aspect-ratio:8/5;background:#fff;touch-action:none;cursor:crosshair;user-select:none;-webkit-user-select:none; }
.exam-sketch.is-read-only canvas { cursor:default;touch-action:pan-y; }
.exam-sketch.is-read-only .exam-sketch-toolbar { background:#f4f5f2; }
.exam-sketch .exam-sketch-hint,.exam-sketch .exam-sketch-status { margin:9px 0 0;font-size:.8125rem;line-height:1.7;color:#52635b; }
.exam-sketch .exam-sketch-status { min-height:23px; }
.exam-sketch .exam-sketch-status[data-error=true] { color:#8d301f;font-weight:600; }
@media(max-width:480px){
  .exam-sketch .exam-sketch-toolbar { align-items:stretch;gap:9px;padding:10px; }
  .exam-sketch .exam-sketch-actions { width:100%; }
  .exam-sketch .exam-sketch-actions button { flex:1 1 auto; }
  .exam-sketch .exam-sketch-heading>span { font-size:.6875rem; }
}

/* ==== exam-progress.css ==== */
.learning-studio .study-home.exam-home-focused .study-welcome { min-height: 168px; padding: 24px 32px 44px; }
.learning-studio .study-home.exam-home-focused .study-welcome::before { content: none; }
.learning-studio .study-home.exam-home-focused .study-welcome > div { padding: 0; }
.learning-studio .study-home.exam-home-focused .study-welcome h1 { font-size: 2rem; }
.study-home.exam-home-focused .study-search { margin: -28px 0 0 32px; min-height: 56px; }
.exam-room .exam-room-tabs { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); }
.exam-room .exam-room-tabs a { min-width: 0; padding-inline: 8px; }
.preparation-home-heading, .preparation-home-next, .preparation-subject-heading, .preparation-question-heading, .preparation-gap { display: flex; justify-content: space-between; align-items: flex-start; gap: 18px; }
.preparation-home-heading h2 { margin: 0 0 8px; }
.preparation-home-status { margin: 24px 0; line-height: 1.75; color: var(--ink,#1d2935); }
.preparation-subjects { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 14px; margin: 22px 0 4px; }
.preparation-subject { min-width: 0; border: 1px solid var(--line,#dce4dd); border-radius: 16px; padding: 18px; background: #fbfcfa; }
.preparation-subject-heading { gap: 10px; }
.learning-studio .preparation-subject-heading h3 { font-size: 1rem; margin: 0; }
.preparation-subject-heading a { font-size: .8125rem; white-space: nowrap; color: #11665a; }
.preparation-subject-count { margin: 18px 0 12px; display: flex; gap: 6px; align-items: baseline; flex-wrap: wrap; }
.preparation-subject-count strong { font-size: 2rem; line-height: 1; color: #11665a; font-variant-numeric: tabular-nums; }
.preparation-subject-count span { font-size: .8125rem; color: #526171; }
.preparation-completion-bar { height: 5px; overflow: hidden; background: #e4eae5; border-radius: 999px; margin: 0 0 12px; }
.preparation-completion-bar span { display: block; height: 100%; background: #197b68; }
.preparation-criteria { margin: 18px 0; }
.preparation-criteria-bar { display: flex; width: 100%; height: 15px; border-radius: 5px; overflow: hidden; background: #dfe5df; }
.preparation-criteria-bar span { min-width: 2px; border-right: 2px solid #fff; }
.preparation-criteria-bar span:last-child { border-right: 0; }
.preparation-criteria [data-level="met"] { --level-color: #15745f; }
.preparation-criteria [data-level="partial"] { --level-color: #c08220; }
.preparation-criteria [data-level="missing"] { --level-color: #b14b39; }
.preparation-criteria [data-level="unsure"] { --level-color: #5c71a0; }
.preparation-criteria [data-level="unassessed"] { --level-color: #c2cbc4; }
.preparation-criteria-bar span, .preparation-dot { background: var(--level-color); }
.preparation-criteria ul { display: flex; flex-wrap: wrap; gap: 8px 20px; list-style: none; padding: 0; margin: 12px 0 0; }
.preparation-criteria li { font-size: .8125rem; display: flex; gap: 6px; align-items: center; color: #526171; }
.preparation-criteria li strong { font-variant-numeric: tabular-nums; color: #263b3b; }
.preparation-dot { display: inline-block; height: 8px; width: 8px; border-radius: 2px; flex-shrink: 0; }
.preparation-criteria-compact { margin: 16px 0 0; }
.preparation-criteria-compact .preparation-criteria-bar { height: 7px; }
.preparation-criteria-compact ul { gap: 6px 12px; }
.preparation-criteria-compact li { font-size: .75rem; }
.preparation-home-next { margin: 24px 0 12px; padding: 20px; border-radius: 14px; background: #eaf4ef; align-items: center; }
.learning-studio .preparation-home-next h3 { margin: 8px 0 6px; font-size: 1.125rem; }
.preparation-home-next p { margin: 0; font-size: .875rem; color: #526171; }
.preparation-filters { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 22px; }
.preparation-filters [aria-current="page"] { background: #11665a; border-color: #11665a; color: #fff; }
.preparation-questions,.preparation-gaps { list-style: none; margin: 0; padding: 0; }
.preparation-question { padding: 22px 0; border-bottom: 1px solid var(--line,#dce4dd); }
.preparation-question:first-child { padding-top: 10px; }
.preparation-question-heading h3 { margin: 5px 0; font-size: 1.05rem; }
.preparation-question-heading h3 a { color: #133e37; }
.preparation-question-heading .exam-badge { flex-shrink: 0; }
.preparation-question .preparation-criteria { margin: 12px 0 0; }
.preparation-change { background: #edf5ef; border-left: 3px solid #1d765f; padding: 12px 14px; font-size: .875rem; line-height: 1.7; }
.preparation-gap { padding: 18px 0; border-bottom: 1px solid var(--line,#dce4dd); align-items: center; }
.preparation-gap > div:first-child { min-width: 0; flex: 1; }
.preparation-gap h3 { font-size: 1rem; margin: 10px 0 6px; }
.preparation-gap .exam-actions { flex-shrink: 0; margin: 0; }
.preparation-diagnostic { background: #f4f6f1; padding: 24px; border-radius: 16px; }
@media (max-width: 1050px) {
 .preparation-subjects { gap: 10px; }
 .preparation-subject { padding: 14px; }
 .preparation-gap { align-items: flex-start; flex-direction: column; }
}
@media (max-width: 760px) {
 .exam-room .exam-room-tabs { grid-template-columns:repeat(2,minmax(0,1fr)); }
 .preparation-subjects { grid-template-columns: 1fr; }
 .preparation-home-heading,.preparation-home-next { flex-direction: column; align-items: stretch; }
 .preparation-home-heading > .exam-button { align-self: flex-start; }
 .preparation-subject .preparation-criteria ul { gap: 7px 15px; }
 .preparation-question-heading { flex-direction: column; gap: 6px; }
 .exam-room .exam-room-tabs a { padding-inline: 7px; font-size: .8125rem; }
 .learning-studio .study-home.exam-home-focused .study-welcome { min-height: 160px; padding: 20px 20px 42px; }
 .learning-studio .study-home.exam-home-focused .study-welcome h1 { font-size: 1.65rem; }
 .learning-studio .study-home.exam-home-focused .study-welcome p { font-size: .9rem; }
 .study-home.exam-home-focused .study-search { width: calc(100% - 28px); margin: -28px 14px 0; }
 .preparation-home-next { padding: 16px; }
 .preparation-filters { gap: 6px; }
 .preparation-filters .exam-button { font-size: .8125rem; padding-inline: 10px; }
}
.preparation-papers > h2 { margin-bottom: .6rem; }
.preparation-papers ul { list-style: none; padding: 0; display: grid; gap: .7rem; }
.preparation-papers li { display: flex; gap: 1rem; justify-content: space-between; align-items: center; padding: 1rem; background: #f4f8f4; border: 1px solid var(--exam-line); border-radius: 12px; }
.preparation-papers li h3 { margin-bottom: .25rem; }
.preparation-papers li p + p { margin-top: .35rem; }
.preparation-papers li > a { flex-shrink: 0; }
.preparation-gap .exam-actions > .exam-small { flex-basis:100%; }
.preparation-remedy-criteria { padding:0; list-style:none; display:grid; gap:8px; margin:12px 0; }
.preparation-remedy-criteria li { display:flex; gap:12px; align-items:flex-start; justify-content:space-between; font-size:.9rem; }
.preparation-remedy-criteria .exam-badge { flex-shrink:0; }
.preparation-gap-group > div:first-child { width:100%; }
@media(max-width:480px) { .preparation-remedy-criteria li { flex-direction:column; gap:4px; } }
@media(max-width:600px) { .preparation-papers li { align-items: stretch; flex-direction: column; } }

