display:flex;align-items:center;gap:8px;margin:16px 0}.paper-question details{border-top:1px solid var(--paper-line);padding:12px 0}.paper-question details>label{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:center}.paper-end-actions{display:flex;gap:12px;flex-wrap:wrap;border-top:1px solid var(--paper-line);padding-top:20px;margin-top:20px}.paper-summary{background:#eef5f6;border-radius:10px;padding:16px 20px;margin:18px 0 24px}.paper-summary h3{margin-top:0}.paper-summary p{line-height:1.7}.paper-sealed-response,.paper-rescue pre{font:inherit;white-space:pre-wrap;overflow-wrap:anywhere;border:1px solid var(--paper-line);padding:16px;border-radius:10px;line-height:1.8}.paper-rescue{background:#fff7ec;border-color:#dba564}.paper-rescue article{border-top:1px solid #e5c9a6;padding:14px 0}.paper-rescue h3{overflow-wrap:anywhere;font-size:1rem}.paper-backup{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:24px;padding-top:20px;border-top:1px solid var(--paper-line)}.paper-backup p{flex-basis:100%;font-size:.87rem;color:var(--paper-muted);line-height:1.65}.paper-import-label{display:inline-flex;align-items:center;gap:8px;max-width:100%}.paper-import-label input{max-width:220px;min-width:0}.paper-shell [hidden]{display:none!important}
