.exam-lesson-bridge li {display:flex;justify-content:space-between;align-items:center;gap:18px;padding:14px 0;border-top:1px solid #dbe6de;}
.exam-lesson-bridge li strong {display:block;font-size:.95rem;}
.exam-lesson-bridge li span {display:block;margin-top:5px;font-size:.82rem;color:#4f5d69;}
